// Generated from the Erbium showcase catalog and shared Markdown.
import { ShowcaseProviders, ShowcaseSurface } from "../preview";
import type { Meta, StoryObj } from "@storybook/react";

import { DirectionProvider } from "@/registry/erbium/ui/direction";

import PlaygroundExample, { defaultProps as PlaygroundDefaults } from "./variants/playground";



import OverviewExample from "./variants/overview";



const meta = {
  component: DirectionProvider,
  parameters: {
    docs: {
      description: {
        component: "## Usage

Wrap your application in the direction provider to set its text direction.

**Import:** `@/registry/erbium/ui/direction`

## Usage

```tsx
import { DirectionProvider } from "@/registry/erbium/ui/direction";
```

```tsx
<html dir="rtl">
  <body>
    <DirectionProvider direction="rtl">{/* Your app content */}</DirectionProvider>
  </body>
</html>
```

## useDirection

The `useDirection` hook is used to get the current direction of the application.

```tsx
import { useDirection } from "@/registry/erbium/ui/direction";

function MyComponent() {
  const direction = useDirection();
  return <div>Current direction: {direction}</div>;
}
```

## Base UI documentation

Explore the underlying primitives and their API reference.

- [Direction Provider](https://base-ui.com/react/utils/direction-provider)",
      },
    },
    layout: "centered",
  },
  tags: ["autodocs"],
} satisfies Meta<typeof DirectionProvider>;

export default { ...meta, title: "Providers/Direction",  decorators: [(Story, context) => <ShowcaseProviders toast={false && context.viewMode !== "docs"}><ShowcaseSurface><Story /></ShowcaseSurface></ShowcaseProviders>] } satisfies Meta;

type Story = StoryObj;

export const Playground: StoryObj<{ direction: "ltr" | "rtl" }> = {
  argTypes: { direction: { control: "select", options: ["ltr", "rtl"] } },
  args: PlaygroundDefaults,
  parameters: {
    docs: {
      description: { story: "" },
      source: { code: "import { DirectionProvider } from "@/registry/erbium/ui/direction";

export const defaultProps = { direction: "ltr" } satisfies { direction: "ltr" | "rtl" };

export default function DirectionPlaygroundExample(
  args: { direction: "ltr" | "rtl" } = defaultProps,
) {
  return (
    <DirectionProvider direction={args.direction}>
      <div dir={args.direction} className="w-72 rounded border p-4">
        Direction: {args.direction}
        <div className="mt-2 flex gap-related">
          <button type="button" className="rounded border p-2">
            First
          </button>
          <button type="button" className="rounded border p-2">
            Second
          </button>
        </div>
      </div>
    </DirectionProvider>
  );
}
" },
    },
  },
  render: PlaygroundExample,
};

